 62	    /**
 63	     * Increment the count for one class of actor.
 64	     * @param actorClass The class of actor to increment.
 65	     */
 66	    public void incrementCount(Class<?> actorClass)
 67	    {
 68	        Counter count = counters.get(actorClass);
 69	        if(count == null) {
 70	            // We do not have a counter for this species yet.
 71	            // Create one.
 72	            count = new Counter(actorClass.getName());
 73	            counters.put(actorClass, count);
 74	        }
 75	        count.increment();
 76	        
 77	    }
