 40	    /**
 41	     * Returns the next weather condition based on the current
 42	     * weather condition and a random generator.
 43	     * @return The next weather condition.
 44	     */
 45	    public WeatherCond nextCondition()
 46	    {
 47	        List<WeatherCond> tempList = new ArrayList<>();
 48	        if (!timeOfDay.isDay()) {
 49	            switch(this) {
 50	                case Sunny:
 51	                    tempList.add(Cloudy);
 52	                    tempList.add(Windy);
 53	                    break;
 54	                case Rain:
 55	                    tempList.add(Storm);
 56	                    tempList.add(Cloudy);
 57	                    break;
 58	                default:
 59	                    tempList.add(Fog);
 60	                    tempList.add(Rain);
 61	                    break;
 62	            }
 63	        }
 64	        else {
 65	            switch(this) {
 66	                case Sunny:
 67	                    tempList.add(Cloudy);
 68	                    tempList.add(Windy);
 69	                    break;
 70	                case Rain:
 71	                    tempList.add(Storm);
 72	                    tempList.add(Cloudy);
 73	                    break;
 74	                default:
 75	                    tempList.add(Sunny);
 76	                    tempList.add(Fog);
 77	                    tempList.add(Rain);
 78	                    break;
 79	            }
 80	        }
 81	        return tempList.get(rand.nextInt((tempList.size())));
